    },
    {
      "year": 2048,
      "event": "The first crewed mission to Mars successfully establishes a long-term research outpost.",
      "detail": "This marks a major step in humanity becoming a multi-planetary species, driven by a consortium of public and private entities."
    },
    {
      "year": 2055,
      "event": "A major global food crisis occurs due to climate-driven agricultural collapse.",
      "detail": "A combination of persistent droughts, heatwaves, and soil degradation in several major breadbasket regions leads to unprecedented food shortages and mass migration."
    },
    {
      "year": 2063,
      "event": "The first large-scale solar geoengineering project is deployed.",
      "detail": "Faced with catastrophic climate impacts, a coalition of nations begins stratospheric aerosol injection to reduce incoming solar radiation, despite major geopolitical controversy and unknown side effects."
    },
    {
      "year": 2075,
