      "year": 2180,
      "event": "The first city on Mars achieves a high degree of self-sufficiency.",
      "detail": "The Martian colony can now produce its own food, water, and essential industrial goods, reducing its dependency on Earth and developing a distinct culture."
    },
    {
      "year": 2250,
      "event": "Most global logistics, infrastructure, and financial markets are managed by a decentralized network of AIs.",
      "detail": "Human oversight is minimal as complex systems become too fast and interconnected for people to manage effectively, leading to unprecedented efficiency but also new systemic risks."
    },
    {
      "year": 2300,
      "event": "The average human lifespan in developed nations surpasses 120 years.",
      "detail": "A combination of nanotechnology, regenerative medicine, and advanced diagnostics makes age-related diseases largely treatable, creating new social structures and challenges."
    },
    {
      "year": 2450,
      "event": "The first commercial nuclear fusion power plants come online, revolutionizing energy production.",
