    },
    {
      "year": 2600,
      "event": "Asteroid mining becomes a cornerstone of the solar system's economy.",
      "detail": "Automated robotic fleets mine asteroids for water, platinum-group metals, and rare earths, fueling off-world construction and reducing resource pressure on Earth."
    },
    {
      "year": 2800,
      "event": "The first conclusive evidence of extraterrestrial microbial life is discovered in the ocean of a Jovian or Saturnian moon.",
      "detail": "A robotic probe exploring the subsurface ocean of Europa or Enceladus confirms the existence of life that originated independently of Earth, fundamentally changing humanity's place in the cosmos."
    },
    {
      "year": 3000,
      "event": "Humanity has become a truly multi-planetary species.",
      "detail": "Significant, self-governing populations exist on the Moon, Mars, and in numerous orbital habitats, with distinct cultures and physiological adaptations beginning to emerge."
    },
    {
      "year": 3200,
      "event": "The first major armed conflict between Earth and an off-world colony occurs.",
      "detail": "Tensions over resources, political autonomy, and cultural divergence escalate into a limited war, highlighting the challenges of governing an interplanetary civilization."
    },
    {
      "year": 3500,
      "event": "A significant portion of the human population exists in fully immersive virtual realities.",
      "detail": "For many, the digital world offers a more desirable existence than the physical one, leading to new forms of society, economy, and consciousness."
    },
    {
      "year": 4000,
      "event": "The first 'post-human' clade is formally recognized.",
      "detail": "Centuries of genetic engineering and cybernetic augmentation lead to a group of individuals whose biological and cognitive abilities are so different from baseline Homo sapiens that they are considered a new (sub)species."
    },
    {
      "year": 4500,
      "event": "The terraforming of Mars reaches a milestone where humans can breathe the atmosphere with a simple filtration mask.",
      "detail": "After millennia of atmospheric processing and ecosystem seeding, the Red Planet becomes significantly more habitable, though still harsh by Earth standards."
    },
    {
      "year": 5000,
      "event": "The first self-replicating interstellar probe is launched towards a nearby star system.",
      "detail": "This 'von Neumann probe' is designed to travel to a new star, create copies of itself using local resources, and send them on to further stars, beginning the exploration of the galaxy."
    },
    {
      "year": 5200,
      "event": "The Greenland Ice Sheet has completely melted.",
      "detail": "As a long-term consequence of earlier centuries' climate change, the final melting of the Greenland ice sheet contributes to a total sea-level rise of over 7 meters from pre-industrial levels, permanently inundating historic coastal cities."
    },
    {
      "year": 6100,
      "event": "The first successful uploading of a human consciousness to a non-biological substrate is achieved.",
      "detail": "This marks the dawn of digital immortality, where an individual's mind can exist and evolve independently of a biological body, though the process is experimental and its philosophical implications are fiercely debated."
    },
    {
      "year": 7000,
      "event": "A new global language, co-developed by AI and humans, becomes the lingua franca of the solar system.",
      "detail": "Designed for maximum clarity and efficiency, this language supplants ancient tongues like English and Mandarin for interstellar commerce, science, and governance."
    },
    {
      "year": 7800,
      "event": "The first generation starship, carrying a crew in suspended animation, is launched towards a promising exoplanet.",
      "detail": "As a hedge against existential risk in the Sol system, this multi-generational mission represents humanity's first concrete attempt to colonize another star."
    },
    {
      "year": 8500,
      "event": "A major solar flare, larger than any in recorded history, devastates unprotected electronic infrastructure.",
      "detail": "While hardened core systems and off-world colonies survive, the event causes a significant technological setback for parts of Earth, leading to a 'digital dark age' in some regions."
    },
    {
      "year": 9000,
      "event": "Humanity has diversified into multiple distinct forms.",
      "detail": "Baseline humans, genetically modified 'post-humans' adapted for different environments, cyborgs, and fully digital consciousnesses coexist, creating a complex and often fractious multi-species civilization."
    },
    {
      "year": 9950,
      "event": "The interstellar probe launched in 5000 reports the successful creation of a new probe in the Trappist-1 system.",
      "detail": "This first extrasolar 'birth' confirms the viability of exponential galactic exploration, though the information takes decades to travel back to the Sol system."
